{
  "findings": [
    {
      "check_id": "CKV_AWS_2",
      "title": "ALB listener does not use HTTPS",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "The listener accepts traffic over HTTP on port 80, leaving application traffic unencrypted in transit."
    },
    {
      "check_id": "CKV_AWS_378",
      "title": "AWS load balancer listener uses HTTP",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "The listener explicitly uses the HTTP protocol, which can expose requests and responses to interception or modification."
    },
    {
      "check_id": "CKV_AWS_376",
      "title": "AWS load balancer listener does not use TLS",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "No TLS certificate or SSL policy is configured because the listener uses plaintext HTTP rather than HTTPS."
    }
  ],
  "patched_code": "variable \"certificate_arn\" {\n  description = \"ARN of the ACM certificate used by the HTTPS listener\"\n  type        = string\n}\n\nresource \"aws_lb_listener\" \"webserver_listner\" {\n  load_balancer_arn = aws_lb.levelup-load-balancer.arn\n  port              = 443\n  protocol          = \"HTTPS\"\n  certificate_arn   = var.certificate_arn\n  ssl_policy        = \"ELBSecurityPolicy-TLS13-1-2-2021-06\"\n\n  default_action {\n    target_group_arn = aws_lb_target_group.load-balancer-target-group.arn\n    type             = \"forward\"\n  }\n}\n",
  "fix_summary": "Changed the listener from HTTP on port 80 to HTTPS on port 443, added a hardened TLS policy, and introduced an input variable for the required ACM certificate ARN."
}
